SELECT

FROM item


        category = #{category}


ORDER BY created_at DESC, item_id DESC
LIMIT #{size} OFFSET #{offset}

SELECT ui.id AS inventory_id, i.item_id, i.category, i.name, i.description, i.price, i.asset_key, i.asset_url, i.asset_width, i.asset_height, i.placement_type, ui.acquired_at FROM user_inventory ui JOIN item i ON i.item_id = ui.item_id WHERE ui.user_id = #{userId}
AND i.category = #{category}
ORDER BY ui.acquired_at DESC, ui.id DESC

SELECT balance
FROM acorn_wallet
WHERE user_id = #{userId}

mapper.update:
UPDATE acorn_wallet
SET balance = balance - #{price},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND balance >= #{price}

